    Bug 1995117 - Fix browser_ext_theme_experiment_message_browser.js. r=mkmelin
    ... when run after browser_ext_message_external.js. There's some weird interaction with a message
    that's no longer displayed but still in memory when setting ui.prefersReducedMotion.

    Since the preference setting was added as an attempt to fix intermittent fails, and it didn't work,
    I see no problem in removing it.

    Differential Revision: https://phabricator.services.mozilla.com/D269171

diff --git a/mail/components/extensions/test/browser/browser_ext_theme_experiment_message_browser.js b/mail/components/extensions/test/browser/browser_ext_theme_experiment_message_browser.js
index 407088ccfc7..dced885e023 100644
--- a/mail/components/extensions/test/browser/browser_ext_theme_experiment_message_browser.js
+++ b/mail/components/extensions/test/browser/browser_ext_theme_experiment_message_browser.js
@@ -19,12 +19,6 @@ add_setup(async () => {

   gFolder = subFolders.test0;
   gMessages = [...subFolders.test0.messages];
-
-  // Reduce animations to prevent intermittent fails due to late theme changes.
-  Services.prefs.setIntPref("ui.prefersReducedMotion", 1);
-  registerCleanupFunction(() => {
-    Services.prefs.clearUserPref("ui.prefersReducedMotion");
-  });
 });

